import static org.junit.Assert.*;

public class KeyPairTest {

    @Test
    public void keyPairConstructorTest() {
        EdDSAPublicKey edDSAPublicKey = Mockito.mock(EdDSAPublicKey.class);
        KeyPair keyPair = new KeyPair(edDSAPublicKey);
        assertNotNull(keyPair);
    }

    @Test
    public void canSignTest() {
        KeyPair keyPair = KeyPair.random();
        assertTrue(keyPair.canSign());
    }

    @Test
    public void fromSecretSeedCharArrayTest() {
        char[] seed = new char[32];
        assertNotNull(KeyPair.fromSecretSeed(seed));
    }

